 if($('priority').value==='setup'&&!historyView&&!sort)rows=[...rows].sort((a,b)=>(a.setup_tier??9)-(b.setup_tier??9)||(a.setup_sort_distance??Infinity)-(b.setup_sort_distance??Infinity)||(a.setup_risk??Infinity)-(b.setup_risk??Infinity)||a.symbol.localeCompare(b.symbol));
 shown=sortedRows(rows);
 $('count').textContent=shown.length.toLocaleString();$('modeName').textContent=mode;$('listTitle').textContent=`${mode} ${historyView?'历史移出名单':'观察名单'}`;$('viewBadge').textContent=historyView?'历史快照':'当前候选';$('history').textContent=historyView?'显示当前选择股票':'历史移出名单';$('rule').textContent=historyView?'历史入选快照，非当前行情。未入选也可能因字段缺失；辅助参考位请重新复核。':preset.rule;
 for(const b of $('modes').children)b.classList.toggle('active',b.dataset.mode===mode);
 const head=$('headings');head.replaceChildren();
 for(const key of order){const def=columnDefinitions.find(c=>c[0]===key);const th=node('th',def[1]+(sort?.[0]===key?(sort[1]?' ↓':' ↑'):''));th.scope='col';th.title=def[2]+' 点击排序；按住拖动可调整栏目位置。';th.draggable=true;th.tabIndex=0;th.setAttribute('aria-sort',sort?.[0]===key?(sort[1]?'descending':'ascending'):'none');const apply=()=>{sort=[key,sort?.[0]===key?!sort[1]:false];render();};th.addEventListener('click',apply);th.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();apply();}});th.addEventListener('dragstart',e=>{dragged=key;e.dataTransfer.setData('text/plain',key);e.dataTransfer.effectAllowed='move';});th.addEventListener('dragover',e=>{e.preventDefault();th.classList.add('drag-over');});th.addEventListener('dragleave',()=>th.classList.remove('drag-over'));th.addEventListener('drop',e=>{e.preventDefault();if(!dragged||dragged===key)return;const target=order.indexOf(key);order.splice(order.indexOf(dragged),1);order.splice(target,0,dragged);try{localStorage.setItem('martin-column-order',JSON.stringify(order));}catch{}dragged=null;render();});head.append(th);}
 const body=$('stocks');body.replaceChildren();
 for(const row of shown){const tr=node('tr');tr.classList.toggle('selected',row.symbol===selected);tr.tabIndex=0;tr.setAttribute('aria-selected',String(row.symbol===selected));for(const key of order){const td=node('td');if(key==='group'){td.append(node('span',valueText(row,key),'group'));}else td.textContent=valueText(row,key);if(key==='security_name')td.className='name';if(['change','Perf.1M','premarket_change'].includes(key)&&Number.isFinite(row[key]))td.className=row[key]>=0?'positive':'negative';td.title=String(valueText(row,key));tr.append(td);}tr.addEventListener('click',()=>selectStock(row));tr.addEventListener('keydown',e=>{if(e.key==='Enter')selectStock(row);});body.append(tr);}
 if(!shown.length){const tr=node('tr');const td=node('td',historyView?'暂没有历史移出记录；历史会随每天更新逐步积累。':'没有符合当前筛选的股票。','empty-row');td.colSpan=order.length;tr.append(td);body.append(tr);}
