let chartData=[],chartPayload=null,chartToken=0,start=0,end=0,hoverIndex=null,period=365,geometry=null,drag=null;
const canvas=$('chart'),ctx=canvas.getContext('2d');
function clearChart(message){chartData=[];chartPayload=null;$('chartEmpty').textContent=message;$('chartEmpty').hidden=false;$('ohlc').textContent='暂无当前股票行情';$('chartSource').textContent='图表仅提供已发布的历史行情；不以模拟数据替代。';$('range').textContent='滚轮缩放 · 拖动平移';drawChart();}
async function selectStock(row){
 selected=row.symbol;const token=++chartToken;$('chartSymbol').textContent=row.symbol;$('chartName').textContent=row.security_name||'';[...$('stocks').children].forEach((tr,i)=>{tr.classList.toggle('selected',shown[i]?.symbol===selected);tr.setAttribute('aria-selected',String(shown[i]?.symbol===selected));});clearChart('加载已发布K线…');
 if(!row.chart){clearChart('该股票的历史K线尚未随本次快照发布。名单与扫描条件不受影响。');return;}
 try{const response=await fetch(row.chart);if(!response.ok)throw Error('图表文件不可用');const payload=await response.json();const data=payload.charts?.[row.symbol]??payload;if(token!==chartToken)return;chartPayload=data;chartData=data.rows;if(!chartData?.length)throw Error('历史行情为空');$('chartEmpty').hidden=true;$('chartSource').textContent=`${data.source} · 截至 ${chartData.at(-1).date} · ${data.adjustment}${data.warning?' · '+data.warning:''}`;setPeriod(period);}
 catch(error){if(token===chartToken)clearChart(`图表加载失败：${error.message}。请稍后重新选择。`);}
}
function setPeriod(days){period=days;if(!chartData.length)return;const cutoff=days===null?'0000-00-00':new Date(new Date(chartData.at(-1).date+'T12:00:00Z').getTime()-days*86400000).toISOString().slice(0,10);start=chartData.findIndex(r=>r.date>=cutoff);if(start<0)start=0;end=chartData.length;hoverIndex=null;for(const b of $('periods').children)b.classList.toggle('active',String(days??'all')===b.dataset.days);drawChart();}
function drawChart(){
 const rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1,w=Math.max(1,rect.width),h=Math.max(1,rect.height);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#111c28';ctx.fillRect(0,0,w,h);if(!chartData.length||end<=start)return;
 const left=12,right=w-65,top=16,bottom=h-74,volTop=h-62,volBottom=h-23,visible=chartData.slice(start,end),prices=visible.flatMap(r=>[r.high,r.low,r.ema9,r.ema21,r.ema50]).filter(Number.isFinite);let lo=Math.min(...prices),hi=Math.max(...prices);const padding=(hi-lo||hi*.02)*.07;lo-=padding;hi+=padding;const step=(right-left)/visible.length,x=i=>left+(i-start+.5)*step,y=v=>bottom-(v-lo)/(hi-lo)*(bottom-top);geometry={left,right,top,bottom,step,lo,hi,w,h};
 ctx.font='9px -apple-system,Segoe UI,sans-serif';ctx.textBaseline='middle';ctx.strokeStyle='#20303e';ctx.lineWidth=.6;for(let i=0;i<=4;i++){const yp=top+(bottom-top)*i/4;ctx.beginPath();ctx.moveTo(left,yp);ctx.lineTo(right,yp);ctx.stroke();ctx.fillStyle='#60788c';ctx.fillText(fmt(hi-(hi-lo)*i/4),right+9,yp);}
 const maxVol=Math.max(1,...visible.map(r=>r.volume||0));
 for(let i=start;i<end;i++){const r=chartData[i],color=r.close>=r.open?'#3caa8d':'#ce737b',xp=x(i);ctx.strokeStyle=color;ctx.lineWidth=.8;ctx.beginPath();ctx.moveTo(xp,y(r.high));ctx.lineTo(xp,y(r.low));ctx.stroke();ctx.fillStyle=color;const body=Math.max(1,Math.min(step*.62,13));ctx.fillRect(xp-body/2,Math.min(y(r.open),y(r.close)),body,Math.max(1,Math.abs(y(r.open)-y(r.close))));if(Number.isFinite(r.volume)){ctx.globalAlpha=.3;const vh=(r.volume/maxVol)*(volBottom-volTop);ctx.fillRect(xp-body/2,volBottom-vh,body,vh);ctx.globalAlpha=1;}}
 for(const [key,color] of [['ema9','#50a0e8'],['ema21','#e5a956'],['ema50','#ae86ce']]){ctx.beginPath();ctx.strokeStyle=color;ctx.lineWidth=.8;let first=true;for(let i=start;i<end;i++){const v=chartData[i][key];if(!Number.isFinite(v))continue;if(first){ctx.moveTo(x(i),y(v));first=false;}else ctx.lineTo(x(i),y(v));}ctx.stroke();}
 ctx.fillStyle='#60788c';ctx.textAlign='center';for(let t=0;t<5;t++){const i=Math.min(end-1,start+Math.floor((end-start-1)*t/4));ctx.fillText(chartData[i].date,x(i),h-9);}ctx.textAlign='left';
 const high=visible.reduce((a,b)=>a.high>=b.high?a:b),low=visible.reduce((a,b)=>a.low<=b.low?a:b);$('range').textContent=`${visible[0].date} — ${visible.at(-1).date} · 高 ${fmt(high.high)} / 低 ${fmt(low.low)}`;
 if(hoverIndex!==null&&hoverIndex>=start&&hoverIndex<end){ctx.setLineDash([3,3]);ctx.strokeStyle='#5c7488';ctx.beginPath();ctx.moveTo(x(hoverIndex),top);ctx.lineTo(x(hoverIndex),volBottom);ctx.stroke();ctx.setLineDash([]);}
 const r=chartData[hoverIndex??end-1];$('ohlc').textContent=`${r.date}  O ${fmt(r.open)}  H ${fmt(r.high)}  L ${fmt(r.low)}  C ${fmt(r.close)}  V ${r.volume===null?'缺失':fmt(r.volume,0)}`;
}
canvas.addEventListener('wheel',e=>{if(!chartData.length||!geometry)return;e.preventDefault();const ratio=Math.max(0,Math.min(1,(e.offsetX-geometry.left)/(geometry.right-geometry.left))),size=end-start,newSize=Math.max(Math.min(10,chartData.length),Math.min(chartData.length,Math.round(size*(e.deltaY<0?.8:1.25)))),anchor=start+ratio*size;start=Math.max(0,Math.min(chartData.length-newSize,Math.round(anchor-ratio*newSize)));end=start+newSize;hoverIndex=null;drawChart();},{passive:false});
canvas.addEventListener('pointerdown',e=>{if(!chartData.length)return;canvas.focus();canvas.setPointerCapture(e.pointerId);drag={x:e.offsetX,start,end};});
canvas.addEventListener('pointermove',e=>{if(!geometry||!chartData.length)return;if(drag){const shift=Math.round((drag.x-e.offsetX)/geometry.step);start=Math.max(0,Math.min(chartData.length-(drag.end-drag.start),drag.start+shift));end=start+drag.end-drag.start;hoverIndex=null;}else hoverIndex=Math.max(start,Math.min(end-1,start+Math.floor((e.offsetX-geometry.left)/geometry.step)));drawChart();});
canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('pointerleave',()=>{if(!drag){hoverIndex=null;drawChart();}});new ResizeObserver(drawChart).observe(canvas.parentElement);
document.addEventListener('keydown',e=>{if(!['ArrowUp','ArrowDown'].includes(e.key)||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)||$('dialog').open||!shown.length)return;e.preventDefault();const index=shown.findIndex(r=>r.symbol===selected),next=Math.max(0,Math.min(shown.length-1,index+(e.key==='ArrowDown'?1:-1)));selectStock(shown[next]);$('stocks').children[next]?.scrollIntoView({block:'nearest'});});
for(const b of $('periods').children)b.addEventListener('click',()=>setPeriod(b.dataset.days==='all'?null:Number(b.dataset.days)));
for(const id of ['search','group','small','priority'])$(id).addEventListener(id==='search'?'input':'change',()=>{if(id==='priority')sort=null;render();});
$('reset').addEventListener('click',()=>{sort=null;$('priority').value='original';render();});$('history').addEventListener('click',()=>{historyView=!historyView;render();});
$('export').addEventListener('click',()=>{const escape=v=>'"'+String(v??'').replace(/^([=+@\t\r])/,'\'$1').replaceAll('"','""')+'"';const text='\ufeff'+[order.map(k=>escape(columnDefinitions.find(c=>c[0]===k)[1])).join(','),...shown.map(r=>order.map(k=>escape(valueText(r,k))).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`Martin_${mode}_${historyView?'history':'current'}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
function showHelp(){const target=$('helpContent');target.replaceChildren();for(const [name,preset]of Object.entries(snapshot?.modes||{})){target.append(node('h3',name),node('p',preset.rule));}const sections=[['如何使用','选择扫描策略 → 筛选均线组 → 点击股票看图。点击栏目名称切换升降序，按住拖动调整栏目位置。恢复初始排序只恢复股票排列，保留栏目位置。↑↓换股票，滚轮缩放，按住图表拖动平移。'],['辅助排序不是Martin本人公式','使用完整日线判断收盘>EMA21>EMA50、EMA9/21附近支撑、内包日或收紧结构。就绪候选要求参考风险0至5%。同阶段按距突破位/ADR20，再按风险排序。所有阈值是程序辅助规则，不代表买点或成功概率。'],['历史移出名单','显示历次保存中曾通过同一扫描模式、当前已不在完整候选名单的股票。历史视图保留当时价格与日期；辅助参考位不沿用。切换不重新计算或联网扫描，点击股票只读取网站已发布的K线文件。'],['更新与数据覆盖','每日北京时间07:40计划更新（美国夏令时收盘后3小时40分，冬令时后2小时40分）；实际可能延迟。失败保留上次页面，以最后成功更新时间和完整交易日为准。覆盖美国交易所目录，默认不含ETF、OTC及已退市证券；部分证券无行情或字段缺失，不代表100%覆盖。'],['历史K线','免费分享版没有实时价格。已发布K线可离线于行情源查看；未获取的股票明确显示缺失。历史行情源、截止日、复权口径分别标注。仅完整日线，不把未收盘价格作为选股依据。']];for(const [title,text]of sections)target.append(node('h3',title),node('p',text));$('dialog').showModal();}
$('help').addEventListener('click',showHelp);$('about').addEventListener('click',showHelp);$('closeDialog').addEventListener('click',()=>$('dialog').close());$('dialog').addEventListener('click',e=>{if(e.target===$('dialog'))$('dialog').close();});
async function init(){try{const response=await fetch('data/manifest.json',{cache:'no-cache'});if(!response.ok)throw Error(`HTTP ${response.status}`);snapshot=await response.json();for(const [name,preset]of Object.entries(snapshot.modes)){const b=node('button');b.dataset.mode=name;b.title=preset.rule;b.append(node('span',name),node('small',preset.current.length));b.addEventListener('click',()=>{mode=name;historyView=false;sort=null;render();});$('modes').append(b);}$('session').textContent=snapshot.complete_session||'未提供';$('coverage').textContent=`${snapshot.matched.toLocaleString()} / ${snapshot.scope.toLocaleString()}`;$('unmatched').textContent=`${snapshot.unmatched} 只未匹配`;const updated=new Date(snapshot.fetched);$('updated').textContent=Number.isNaN(updated.getTime())?snapshot.fetched:updated.toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});const stale=Date.now()-updated.getTime()>72*3600*1000;$('freshness').textContent=stale?'快照超过72小时，请留意日期':`已发布 · ${snapshot.chart_count} 只K线`;render();}catch(error){$('loadError').hidden=false;$('loadError').textContent=`选股快照读取失败：${error.message}。请刷新页面重试。`;$('results').textContent='无法读取数据';clearChart('尚无可用数据');}}
init();
